// And groups predicates with the AND operator between them.
func And(predicates ...predicate.InvoiceContractAssociation) predicate.InvoiceContractAssociation {
	return predicate.InvoiceContractAssociation(sql.AndPredicates(predicates...))
}

// Or groups predicates with the OR operator between them.
func Or(predicates ...predicate.InvoiceContractAssociation) predicate.InvoiceContractAssociation {
	return predicate.InvoiceContractAssociation(sql.OrPredicates(predicates...))
}

// Not applies the not operator on the given predicate.
func Not(p predicate.InvoiceContractAssociation) predicate.InvoiceContractAssociation {
	return predicate.InvoiceContractAssociation(sql.NotPredicates(p))
}
